import json
from pathlib import Path


class WorkspaceIndex:
    """Minimal deterministic index over a workspace tree."""

    def __init__(self, root: Path) -> None:
        self.root = root
        self.files: dict[str, int] = {}

    def scan(self, suffix: str = ".py") -> dict[str, int]:
        for path in sorted(self.root.rglob("*" + suffix)):
            if "__pycache__" in path.parts:
                continue
            self.files[path.relative_to(self.root).as_posix()] = path.stat().st_size
        return self.files

    def total_bytes(self) -> int:
        return sum(self.files.values())


def main() -> int:
    index = WorkspaceIndex(Path.cwd())
    index.scan()
    print(json.dumps({"files": len(index.files), "bytes": index.total_bytes()}))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

