  { key: 'DATABASE_URL', required: true },
  { key: 'JWT_SECRET', required: true },
  { key: 'PORT', required: true },
  { key: 'API_KEY', required: true },
  { key: 'NODE_ENV', required: false, fallback: 'development' },
