/// The returned slice must borrow from `input` and never allocate.
pub fn longest_word(input: &str) -> &str {
    let mut best = String::new();
    for word in input.split_whitespace() {
        if word.len() > best.len() {
            best = word.to_string();
        }
    }
    best.as_str()
