/// Largest sum over all contiguous windows of exactly `k` samples.
///
/// Returns `None` when `k` is zero or exceeds `samples.len()`.
pub fn max_window_sum(samples: &[i64], k: usize) -> Option<i64> {
    if k == 0 || samples.len() < k {
        return None;
    }
    samples
        .windows(k)
        .take(samples.len() - k)
        .fold(None, |best: Option<i64>, window| {
            let total: i64 = window.iter().sum();
            match best {
                Some(current) if current >= total => Some(current),
                _ => Some(total),
            }
        })
}

/// Index of the first window of `k` consecutive samples whose sum is
/// strictly greater than `limit`.
///
/// Returns `None` when no window qualifies, when `k` is zero, or when
/// `k` exceeds `readings.len()`.
pub fn first_hot_window(readings: &[i64], k: usize, limit: i64) -> Option<usize> {
    if k == 0 || readings.len() < k {
        return None;
    }
    readings
        .windows(k)
        .enumerate()
        .fold(None, |found: Option<usize>, (index, window)| {
            let total: i64 = window.iter().sum();
            if total > limit {
                Some(index)
            } else {
                found
            }
        })
}"}, {"path": "tests/scanner.rs", "content_hash": "6c13e5ff96a2a207", "text": "use scanner::{first_hot_window, max_window_sum};

#[test]
fn max_window_sum_uses_every_full_window() {
    // windows of 2 over [1, 2, 3]: [1, 2] = 3, [2, 3] = 5
    assert_eq!(max_window_sum(&[1, 2, 3], 2), Some(5));
}

#[test]
fn max_window_sum_accepts_a_window_covering_the_whole_slice() {
    assert_eq!(max_window_sum(&[4, -1, 7], 3), Some(10));
}

#[test]
fn max_window_sum_prefers_the_trailing_window_for_negative_samples() {
    // windows of 1: -5, -3, -1
    assert_eq!(max_window_sum(&[-5, -3, -1], 1), Some(-1));
}

#[test]
fn max_window_sum_rejects_degenerate_window_sizes() {
    assert_eq!(max_window_sum(&[1, 2, 3], 0), None);
    assert_eq!(max_window_sum(&[1, 2, 3], 4), None);
}

#[test]
fn first_hot_window_reports_the_earliest_hot_window() {
    // windows of 1 over [1, 9, 9, 1]: hot at indices 1 and 2
    assert_eq!(first_hot_window(&[1, 9, 9, 1], 1, 5), Some(1));
